class TestCreateImageArgumentContract:
    """Verify create-image is called with positional prompt, not --prompt flag."""

    def test_run_sh_uses_uv_run_script(self):
        """run.sh must use 'uv run --script' for PEP 723 deps."""
        run_sh = PI_SKILLS_DIR / "create-image" / "run.sh"
        if not run_sh.exists():
            pytest.skip("create-image skill not found")

        content = run_sh.read_text()
        assert "uv run --script" in content, (
            "run.sh must use 'uv run --script generate.py' for PEP 723 inline deps"
        )
        # Must NOT use bare 'python generate.py'
        assert "python generate.py" not in content.replace("uv run --script generate.py", ""), (
            "run.sh must not use bare 'python generate.py'"
        )

    def test_generate_phase_uses_positional_prompt(self):
        """phases/generate.py must pass prompt as positional arg to create-image."""
        generate_py = SKILL_DIR / "create_movie" / "phases" / "generate.py"
        if not generate_py.exists():
            pytest.skip("phases/generate.py not found")

        content = generate_py.read_text()
        # The create-image call should use positional prompt: ["generate", visual_prompt, ...]
        # NOT: ["generate", "--prompt", visual_prompt, ...]
        # Note: "--prompt" may legitimately appear for OTHER skills (e.g., create-score)
        assert '"generate", visual_prompt,' in content, (
            "create-image must be called with positional prompt"
        )
        assert '"generate", "--prompt", visual_prompt' not in content, (
            "create-image must NOT use --prompt flag"
        )


