class TestSoundDesignDuration:
    """Verify create-sound-design reads per-scene durations."""

    def test_load_scene_durations_from_script(self, tmp_path):
        """_load_scene_durations reads actual durations from script JSON."""
        sd_dir = PI_SKILLS_DIR / "create-sound-design"
        if not sd_dir.exists():
            pytest.skip("create-sound-design skill not found")

        sys.path.insert(0, str(sd_dir))
        from create_sound_design.orchestrator import _load_scene_durations

        script_data = {
            "duration_seconds": 120,
            "scenes": [
                {"id": "scene_01", "duration": 45.0},
                {"id": "scene_02", "duration": 75.0},
            ],
        }

        script_file = tmp_path / "script.json"
        script_file.write_text(json.dumps(script_data))

        durations = _load_scene_durations(str(script_file), 2)
        assert durations["scene_01"] == 45.0
        assert durations["scene_02"] == 75.0

    def test_load_scene_durations_fallback_to_split(self, tmp_path):
        """Falls back to evenly splitting total duration when per-scene duration missing."""
        sd_dir = PI_SKILLS_DIR / "create-sound-design"
        if not sd_dir.exists():
            pytest.skip("create-sound-design skill not found")

        sys.path.insert(0, str(sd_dir))
        from create_sound_design.orchestrator import _load_scene_durations

        script_data = {
            "duration_seconds": 90,
            "scenes": [
                {"id": "scene_01"},
                {"id": "scene_02"},
                {"id": "scene_03"},
            ],
        }

        script_file = tmp_path / "script.json"
        script_file.write_text(json.dumps(script_data))

        durations = _load_scene_durations(str(script_file), 3)
        assert durations["scene_01"] == 30.0
        assert durations["scene_02"] == 30.0
        assert durations["scene_03"] == 30.0
